6	#include "torch_kernel_helper.h"
7	#include "tiling/platform/platform_ascendc.h"
8	#include "aclrtlaunch_grouped_matmul_slice_k_per_token_dequant.h"
9	#include "grouped_matmul_slice_k_per_token_dequant_tiling.h"
10	
