13	namespace ascend_kernel {
14	
15	static int32_t AlignUp(int32_t val, int32_t alignment)
16	{
17	    return ((val + alignment - 1) / alignment) * alignment;
18	}
19	
20	at::Tensor grouped_matmul_slice_k_per_token_dequant(
21	    const at::Tensor &a, const at::Tensor &b,
22	    const at::Tensor &scale, const at::Tensor &per_token_scale,
23	    const at::Tensor &group_list)
24	{
25	    TORCH_CHECK(a.dim() == 2, "a must be 2D");
26	    TORCH_CHECK(b.dim() == 2, "b must be 2D");
27	    TORCH_CHECK(scale.dim() == 2, "scale must be 2D [groupCount, N]");
28	    TORCH_CHECK(per_token_scale.dim() == 2, "per_token_scale must be 2D [groupCount, M]");
29	    TORCH_CHECK(group_list.dim() == 1, "group_list must be 1D");
30	    TORCH_CHECK(a.sizes()[0] == per_token_scale.sizes()[1], "M dimension must match");
31	    TORCH_CHECK(b.sizes()[1] == scale.sizes()[1], "N dimension must match");
32	    TORCH_CHECK(a.scalar_type() == at::kChar, "a must be int8");
33	    TORCH_CHECK(b.scalar_type() == at::kChar, "b must be int8");
34	    TORCH_CHECK(scale.scalar_type() == at::kBFloat16, "scale must be bfloat16");
35	    TORCH_CHECK(per_token_scale.scalar_type() == at::kBFloat16, "per_token_scale must be bfloat16");
36	
37	    at::Tensor a_contig = a.contiguous();
38	    at::Tensor b_contig = b.contiguous();
39	    at::Tensor scale_contig = scale.contiguous();
40	    at::Tensor pt_scale_contig = per_token_scale.contiguous();
41	    at::Tensor group_list_cpu = group_list.to(at::kCPU);
42	
43	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
44	    int64_t usedCoreNum = 2;
45	
46	    // For MIX_AIC_1_2: blockDim = usedCoreNum (each block has 1 AIC + 2 AIV)
47	
48	    int32_t m = static_cast<int32_t>(a_contig.sizes()[0]);
49	    int32_t n = static_cast<int32_t>(b_contig.sizes()[1]);
50	    int32_t k_total = static_cast<int32_t>(a_contig.sizes()[1]);
51	    int32_t group_count = static_cast<int32_t>(group_list.sizes()[0]);
52	
53	    // Preallocate flat output
54	    at::Tensor out_flat = at::empty({static_cast<int64_t>(group_count) * m * n},
55	                                    at::device(at::kPrivateUse1).dtype(at::kBFloat16));
56	
57	    auto *raw_a = a_contig.data_ptr<int8_t>();
58	    auto *raw_b = b_contig.data_ptr<int8_t>();
59	
60	    int32_t start_idx = 0;
61	    const int64_t *group_data = group_list_cpu.data_ptr<int64_t>();
62	
63	    for (int32_t ind = 0; ind < group_count; ++ind) {
64	        int64_t end_idx = group_data[ind];
65	        int32_t k = static_cast<int32_t>(end_idx) - start_idx;
66	
67	        if (k > 0) {
68	            // Pad dimensions
69	            int32_t m_pad = AlignUp(m, BASE_M);
70	            int32_t n_pad = AlignUp(n, BASE_N);
71	            int32_t k_pad = AlignUp(k, BASE_K);
72	
73	            // Create padded A [m_pad, k_pad] with zeros in padding area
74	            at::Tensor a_pad = at::zeros({static_cast<int64_t>(m_pad), static_cast<int64_t>(k_pad)},
75	                                          at::device(at::kPrivateUse1).dtype(at::kChar));
76	            // Copy [m, k] slice of a into a_pad[:, :k]
77	            at::Tensor a_view = a_pad.slice(1, 0, k);
78	            a_view.copy_(a_contig.slice(1, start_idx, static_cast<int64_t>(end_idx)));
79	
80	            // Create padded B [k_pad, n_pad]
81	            at::Tensor b_pad = at::zeros({static_cast<int64_t>(k_pad), static_cast<int64_t>(n_pad)},
82	                                          at::device(at::kPrivateUse1).dtype(at::kChar));
83	            at::Tensor b_view = b_pad.slice(0, 0, k).slice(1, 0, n);
84	            b_view.copy_(b_contig.slice(0, start_idx, static_cast<int64_t>(end_idx)));
85	
86	            // Padded scale [n_pad] (float32)
87	            at::Tensor scale_orig = scale_contig[ind].to(at::kFloat).contiguous();
88	            at::Tensor scale_pad = at::zeros({static_cast<int64_t>(n_pad)},
89	                                              at::device(at::kPrivateUse1).dtype(at::kFloat));
90	            scale_pad.slice(0, 0, n).copy_(scale_orig);
91	
92	            // Padded per_token_scale [m_pad] (float32)
93	            at::Tensor pt_scale_orig = pt_scale_contig[ind].to(at::kFloat).contiguous();
94	            at::Tensor pt_scale_pad = at::zeros({static_cast<int64_t>(m_pad)},
95	                                                 at::device(at::kPrivateUse1).dtype(at::kFloat));
96	            pt_scale_pad.slice(0, 0, m).copy_(pt_scale_orig);
97	
98	            // Output [m_pad, n_pad]
99	            at::Tensor c_pad = at::empty({static_cast<int64_t>(m_pad), static_cast<int64_t>(n_pad)},
100	                                          at::device(at::kPrivateUse1).dtype(at::kBFloat16));
101	
102	            // Tiling
103	            at::Tensor t = at::empty({static_cast<int64_t>(sizeof(GroupedMatmulSliceKPerTokenDequantTiling))},
104	                                     at::device(at::kCPU).dtype(at::kByte));
105	            auto *tiling_ptr = reinterpret_cast<GroupedMatmulSliceKPerTokenDequantTiling *>(t.data_ptr());
106	            tiling_ptr->M = m;
107	            tiling_ptr->N = n;
108	            tiling_ptr->K = k;
109	            tiling_ptr->M_pad = m_pad;
110	            tiling_ptr->N_pad = n_pad;
111	            tiling_ptr->K_pad = k_pad;
112	            auto tiling_npu = t.to(at::kPrivateUse1);
113	
114	            // Workspace
115	            int64_t workSpaceSize = static_cast<int64_t>(BASE_M) * BASE_N *
116	                                    WORKSPACE_DEPTH * sizeof(int32_t) * usedCoreNum;
117	            at::Tensor w = at::empty({workSpaceSize},
118	                                     at::device(at::kPrivateUse1).dtype(at::kByte));
119	
120	            // Launch kernel
121	            uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
122	            EXEC_KERNEL_CMD(grouped_matmul_slice_k_per_token_dequant, blockDim,
123	                            a_pad, b_pad, scale_pad, pt_scale_pad, c_pad, w, tiling_npu);
124	
125	            // Trim output to [m, n] and copy to flat output
126	            at::Tensor c_valid = c_pad.slice(0, 0, m).slice(1, 0, n);
127	            int64_t offset = static_cast<int64_t>(ind) * m * n;
128	            out_flat.slice(0, offset, offset + static_cast<int64_t>(m) * n)
129	                .copy_(c_valid.reshape({-1}));
130	        } else {
131	            // Empty group: fill output slice with zeros
132	            int64_t offset = static_cast<int64_t>(ind) * m * n;
133	            out_flat.slice(0, offset, offset + static_cast<int64_t>(m) * n).zero_();
134	        }
135	
136	        start_idx = static_cast<int32_t>(end_idx);
137	    }
138	
139	    return out_flat;
140	}
141	
142	} // namespace ascend_kernel
