20	template <typename aType, typename bType, typename cType>
21	class BasicMatmulKernel {
22	public:
23	    __aicore__ inline BasicMatmulKernel() {}
24	    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c,
25	                                GM_ADDR tiling, TPipe *pipe);
26	    __aicore__ inline void Process();
27	
28	    MatmulKernel<aType, bType, cType> mm_;
29	    GlobalTensor<aType> aGM_;
30	    GlobalTensor<bType> bGM_;
31	    GlobalTensor<cType> cGM_;
32	    BasicMatmulTiling tiling_;
33	    BlockScheduler sched_;
34	};
35	
36	template <typename aType, typename bType, typename cType>
37	__aicore__ inline void BasicMatmulKernel<aType, bType, cType>::Init(
38	    GM_ADDR a, GM_ADDR b, GM_ADDR c,
39	    GM_ADDR tilingGM, TPipe *pipe)
40	{
41	    CopyTiling(&tiling_, tilingGM);
42	    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ aType *>(a),
43	                         tiling_.M * tiling_.K);
44	    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bType *>(b),
45	                         tiling_.K * tiling_.N);
46	    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ cType *>(c),
47	                         tiling_.M * tiling_.N);
48	
49	    int coreIdx = GetBlockIdx() / GetSubBlockNum();
50	    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN,
51	                GetBlockNum(), coreIdx);
52	
53	    mm_.Init(tiling_.K, tiling_.K, tiling_.N,
54	             tiling_.baseM, tiling_.baseN, tiling_.baseK, tiling_.l1Prefetch,
55	             *pipe);
56	}
57	
58	template <typename aType, typename bType, typename cType>
59	__aicore__ inline void BasicMatmulKernel<aType, bType, cType>::Process()
60	{
61	    int mIdx, nIdx;
62	    while (sched_.HasNext()) {
63	        sched_.Next(mIdx, nIdx);
64	
65	        auto aBlock = aGM_[mIdx * tiling_.baseM * tiling_.K];
66	        auto bBlock = bGM_[nIdx * tiling_.baseN];
67	        auto cBlock = cGM_[mIdx * tiling_.baseM * tiling_.N +
68	                           nIdx * tiling_.baseN];
69	
70	        mm_.ComputeBlock(aBlock, bBlock, cBlock);
71	    }
72	}
