20	template<typename T>
21	__aicore__ inline void CopyTiling(T *tiling, GM_ADDR tilingGM)
22	{
23	    int32_t *ptr = reinterpret_cast<int32_t *>(tiling);
24	    auto tiling32 = reinterpret_cast<__gm__ int32_t *>(tilingGM);
25	    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i, ++ptr) {
26	        *ptr = *(tiling32 + i);
27	    }
28	}
