30	class BlockScheduler {
31	public:
32	    __aicore__ inline void Init(int M, int N, int baseM, int baseN, int numBlocks, int blockIdx)
33	    {
34	        if (baseM == 0 || baseN == 0 || numBlocks == 0) {
35	            mBlocks_ = 0;
36	            nBlocks_ = 0;
37	            startBlock_ = 0;
38	            endBlock_ = 0;
39	            current_ = 0;
40	            return;
41	        }
42	        mBlocks_ = M / baseM;
43	        nBlocks_ = N / baseN;
44	        int totalBlocks = mBlocks_ * nBlocks_;
45	        int blocksPerCore = totalBlocks / numBlocks;
46	        int remainder = totalBlocks % numBlocks;
47	        startBlock_ = blockIdx * blocksPerCore + (blockIdx < remainder ? blockIdx : remainder);
48	        endBlock_ = startBlock_ + blocksPerCore + (blockIdx < remainder ? 1 : 0);
49	        current_ = startBlock_;
50	    }
51	
52	    __aicore__ inline bool HasNext()
53	    {
54	        return current_ < endBlock_;
55	    }
56	
57	    __aicore__ inline void Next(int &mIdx, int &nIdx)
58	    {
59	        mIdx = current_ / nBlocks_;
60	        nIdx = current_ % nBlocks_;
61	        current_++;
62	    }
63	
64	private:
65	    int mBlocks_;
66	    int nBlocks_;
67	    int startBlock_;
68	    int endBlock_;
69	    int current_;
70	};
71	
72	#endif // KERNEL_COMMON_H
