16	
17	// CRTP base for MatmulKernel templates.
18	template <typename Derived, typename aType, typename bType, typename cType>
19	class MatmulKernelBase {
20	    static_assert(std::is_same<aType, bType>::value, "aType and bType must be the same type");
21	    static constexpr uint32_t C0 = 32 / sizeof(aType);
22	
23	public:
24	    __aicore__ inline MatmulKernelBase() {}
25	    __aicore__ inline void ComputeBlock(const AscendC::GlobalTensor<aType> &aBlock,
26	                                        const AscendC::GlobalTensor<bType> &bBlock,
27	                                        const AscendC::GlobalTensor<cType> &cBlock);
28	
29	protected:
30	    AscendC::TQue<AscendC::TPosition::A1, 1> inQueueA1;
31	    AscendC::TQue<AscendC::TPosition::A2, 1> inQueueA2;
32	    AscendC::TQue<AscendC::TPosition::B1, 1> inQueueB1;
33	    AscendC::TQue<AscendC::TPosition::B2, 1> inQueueB2;
34	    AscendC::TQue<AscendC::TPosition::CO1, 1> outQueueCO1;
35	
36	    uint32_t k_;
37	    uint32_t a_dvalue_, b_dvalue_;
38	
39	    __aicore__ inline void CopyA(const AscendC::GlobalTensor<aType> &A, uint32_t kLen);
40	    __aicore__ inline void CopyB(const AscendC::GlobalTensor<bType> &B, uint32_t kLen);
41	    __aicore__ inline void SplitA(const AscendC::LocalTensor<aType> &a1Local,
42	                                  uint32_t offset, uint32_t colC0Stride);
43	    __aicore__ inline void SplitB(const AscendC::LocalTensor<bType> &b1Local,
44	                                  uint32_t offset, uint32_t colC0Stride);
45	    __aicore__ inline void Compute(const AscendC::LocalTensor<cType> &c1Local, bool cmatrixInitVal);
46	    __aicore__ inline void CopyOut(const AscendC::GlobalTensor<cType> &C);
47	
48	private:
49	    __aicore__ inline Derived &self() { return static_cast<Derived &>(*this); }
50	    __aicore__ inline const Derived &self() const { return static_cast<const Derived &>(*this); }
51	};
52	
53	template <typename Derived, typename aType, typename bType, typename cType>
54	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::ComputeBlock(
55	    const AscendC::GlobalTensor<aType> &aBlock,
56	    const AscendC::GlobalTensor<bType> &bBlock,
57	    const AscendC::GlobalTensor<cType> &cBlock)
58	{
59	    AscendC::LocalTensor<cType> c1Local = outQueueCO1.AllocTensor<cType>();
60	    uint32_t kTiles = k_ / self().base_k();
61	
62	    for (uint32_t outer = 0; outer < kTiles; outer += self().l1_prefetch()) {
63	        uint32_t count = (kTiles - outer < self().l1_prefetch())
64	                             ? (kTiles - outer) : self().l1_prefetch();
65	        uint32_t kLen = count * self().base_k();
66	
67	        CopyA(aBlock[outer * self().base_k()], kLen);
68	        CopyB(bBlock[outer * self().base_k() * b_dvalue_], kLen);
69	
70	        AscendC::LocalTensor<aType> a1Local = inQueueA1.DeQue<aType>();
71	        AscendC::LocalTensor<bType> b1Local = inQueueB1.DeQue<bType>();
72	
73	        for (uint32_t i = 0; i < count; i++) {
74	            SplitA(a1Local, i * self().base_mk(), self().base_m());
75	            SplitB(b1Local, i * self().base_k() * C0, kLen);
76	            Compute(c1Local, (outer + i == 0));
77	        }
78	
79	        inQueueA1.FreeTensor(a1Local);
80	        inQueueB1.FreeTensor(b1Local);
81	    }
82	
83	    outQueueCO1.EnQue(c1Local);
84	    CopyOut(cBlock);
85	}
86	
87	template <typename Derived, typename aType, typename bType, typename cType>
88	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyA(
89	    const AscendC::GlobalTensor<aType> &A, uint32_t kLen)
90	{
91	    auto a1Local = inQueueA1.AllocTensor<aType>();
92	    LoadNdGmToNzL1(a1Local, A, self().base_m(), kLen, a_dvalue_);
93	    inQueueA1.EnQue(a1Local);
94	}
95	
96	template <typename Derived, typename aType, typename bType, typename cType>
97	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyB(
98	    const AscendC::GlobalTensor<bType> &B, uint32_t kLen)
99	{
100	    AscendC::LocalTensor<bType> b1Local = inQueueB1.AllocTensor<bType>();
101	    LoadNdGmToNzL1(b1Local, B, kLen, self().base_n(), b_dvalue_);
102	    inQueueB1.EnQue(b1Local);
103	}
104	
105	template <typename Derived, typename aType, typename bType, typename cType>
106	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::SplitA(
107	    const AscendC::LocalTensor<aType> &a1Local, uint32_t offset, uint32_t colC0Stride)
108	{
109	    AscendC::LocalTensor<aType> a2Local = inQueueA2.AllocTensor<aType>();
110	    LoadNzL1ToZzL0A(a2Local, a1Local[offset], self().base_m(), self().base_k(), colC0Stride);
111	    inQueueA2.EnQue(a2Local);
112	}
113	
114	template <typename Derived, typename aType, typename bType, typename cType>
115	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::SplitB(
116	    const AscendC::LocalTensor<bType> &b1Local, uint32_t offset, uint32_t colC0Stride)
117	{
118	    AscendC::LocalTensor<bType> b2Local = inQueueB2.AllocTensor<bType>();
119	    LoadNzL1ToZnL0B(b2Local, b1Local[offset], self().base_k(), self().base_n(), colC0Stride);
120	    inQueueB2.EnQue(b2Local);
121	}
122	
123	template <typename Derived, typename aType, typename bType, typename cType>
124	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::Compute(
125	    const AscendC::LocalTensor<cType> &c1Local, bool cmatrixInitVal)
126	{
127	    AscendC::LocalTensor<aType> a2Local = inQueueA2.DeQue<aType>();
128	    AscendC::LocalTensor<bType> b2Local = inQueueB2.DeQue<bType>();
129	    AscendC::MmadParams mmadParams;
130	    mmadParams.m = self().base_m();
131	    mmadParams.n = self().base_n();
132	    mmadParams.k = self().base_k();
133	    mmadParams.cmatrixInitVal = cmatrixInitVal;
134	    AscendC::Mmad(c1Local, a2Local, b2Local, mmadParams);
135	    inQueueA2.FreeTensor(a2Local);
136	    inQueueB2.FreeTensor(b2Local);
137	}
