139	template <typename Derived, typename aType, typename bType, typename cType>
140	__aicore__ inline void MatmulKernelBase<Derived, aType, bType, cType>::CopyOut(
141	    const AscendC::GlobalTensor<cType> &C)
142	{
143	    auto c1Local = outQueueCO1.DeQue<cType>();
144	    FixpipeNzL0cToNdGm(C, c1Local, self().base_m(), self().base_n());
145	    outQueueCO1.FreeTensor(c1Local);
146	}
