41	template <typename aType, typename bType, typename cType>
42	__aicore__ inline void MatmulKernel<aType, bType, cType>::Init(
43	    uint32_t k, uint32_t lda, uint32_t ldb, AscendC::TPipe &pipe)
44	{
45	    ASSERT(k % baseK == 0);
46	    this->k_ = k;
47	    this->a_dvalue_ = lda;
