52	    pipe.InitBuffer(this->inQueueB1, 2, baseKN * L1_PREFETCH * sizeof(bType));
53	    pipe.InitBuffer(this->inQueueB2, 2, baseKN * sizeof(bType));
54	    pipe.InitBuffer(this->outQueueCO1, 1, baseMN * sizeof(cType));
