65	// 参数只有k,n, 只适用于整个基本块, 支持任意2字节类型 (half, bfloat16_t, ...)
66	template<typename T>
67	__aicore__ inline void LoadNzL1ToZnL0B(const AscendC::LocalTensor<T> &dst,
68	                                       const AscendC::LocalTensor<T> &src,
69	                                       uint32_t k, uint32_t n, uint32_t colC0Stride)
70	{
71	    AscendC::LoadData3DParamsV2<T> params;
72	    params.l1H = 1;
73	    params.l1W = colC0Stride;
74	    params.channelSize = n;
75	    params.kExtension = n;
76	    params.mExtension = k;
77	    params.strideH = 1;
78	    params.strideW = 1;
79	    params.filterH = 1;
80	    params.filterW = 1;
81	    params.dilationFilterH = 1;
82	    params.dilationFilterW = 1;
83	    AscendC::LoadData(dst, src, params);
