86	// L1(Nz) -> L0B(Zn)
87	// 参数只有k,n, 只适用于整个基本块
88	__aicore__ inline void LoadNzL1ToZnL0B(const AscendC::LocalTensor<int8_t> &dst,
89	                                       const AscendC::LocalTensor<int8_t> &src,
90	                                       uint32_t k, uint32_t n, uint32_t colC0Stride)
91	{
92	    static constexpr uint32_t FRAC_M  = 16;
93	    static constexpr uint32_t FRAC_N  = 16;
94	    static constexpr uint32_t C0_SIZE = 32;
95	    static constexpr uint32_t FRAC_K  = C0_SIZE;
96	    uint32_t dstOffset = FRAC_K * n;
97	    uint32_t srcOffset = FRAC_K * C0_SIZE;
98	    // Nz -> Zn
99	    AscendC::LoadData2dTransposeParams loadDataParams;
100	    loadDataParams.repeatTimes = n / C0_SIZE;
101	    loadDataParams.srcStride = colC0Stride / FRAC_K;
102	    loadDataParams.dstGap = 1;
103	    loadDataParams.dstFracGap = 0;
104	    for (int i = 0; i < k / FRAC_K; ++i) {
105	        AscendC::LoadDataWithTranspose(dst[i * dstOffset], src[i * srcOffset], loadDataParams);
106	    }
107	}
