113	template<typename T>
114	__aicore__ inline void FixpipeNzL0cToNdGm(const AscendC::GlobalTensor<T> &dst,
115	                                      const AscendC::LocalTensor<T> &src,
116	                                      uint32_t m, uint32_t n)
117	{
118	    AscendC::FixpipeParamsV220 params;
119	    params.nSize = n;
120	    params.mSize = m;
121	    params.srcStride = m;
122	    params.dstStride = n;
123	    params.ndNum = 1;
124	    params.srcNdStride = 0;
125	    params.dstNdStride = 0;
126	    AscendC::Fixpipe(dst, src, params);
127	}
