26	#define CUBE_NOTIFY_VECTOR_ID 0x8
27	#define VECTOR_NOTIFY_CUBE_ID 0x9
28	
29	using namespace AscendC;
30	
31	class GroupedMatmulSliceKPerTokenDequantKernel {
32	public:
33	    __aicore__ inline GroupedMatmulSliceKPerTokenDequantKernel() {}
34	    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
35	                                GM_ADDR c, GM_ADDR workspace, GM_ADDR tiling, AscendC::TPipe *pipe);
36	    __aicore__ inline void Process();
37	
38	    MatmulKernel<int8_t, int8_t, int32_t> mm_;
39	    AscendC::GlobalTensor<int8_t> aGM_;
40	    AscendC::GlobalTensor<int8_t> bGM_;
41	    AscendC::GlobalTensor<float> scaleGM_;
42	    AscendC::GlobalTensor<float> ptScaleGM_;
43	    AscendC::GlobalTensor<bfloat16_t> cGM_;
44	    WorkspaceQueue<int32_t, WORKSPACE_DEPTH> wsQueue_;
45	    GroupedMatmulSliceKPerTokenDequantTiling tiling;
46	    DequantKernel<int32_t, bfloat16_t> dequantKernel_;
47	    BlockScheduler sched_;
48	    int subTileM_;
49	};
50	
51	__aicore__ inline void GroupedMatmulSliceKPerTokenDequantKernel::Init(
52	    GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
53	    GM_ADDR c, GM_ADDR workspace, GM_ADDR tilingGM, AscendC::TPipe *pipe)
54	{
55	    CopyTiling(&this->tiling, tilingGM);
56	
57	    // Use padded dimensions for computation
58	    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling.M_pad * tiling.K_pad);
59	    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling.K_pad * tiling.N_pad);
60	    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling.N_pad);
61	    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(perTokenScale), tiling.M_pad);
62	    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(c), tiling.M_pad * tiling.N_pad);
63	
64	    int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
65	    sched_.Init(tiling.M_pad, tiling.N_pad, BASE_M, BASE_N,
66	                AscendC::GetBlockNum(), coreIdx);
67	
68	    uint32_t wsOffset = coreIdx * WORKSPACE_DEPTH * BASE_M * BASE_N;
69	    wsQueue_.Init(workspace + wsOffset * sizeof(int32_t),
70	                  BASE_M * BASE_N,
71	                  CUBE_NOTIFY_VECTOR_ID, VECTOR_NOTIFY_CUBE_ID);
72	
73	    if ASCEND_IS_AIC {
74	        mm_.Init(tiling.K_pad, tiling.K_pad, tiling.N_pad, *pipe);
75	    }
76	
77	    if ASCEND_IS_AIV {
78	        subTileM_ = BASE_M / AscendC::GetSubBlockNum();
79	        dequantKernel_.Init(subTileM_, BASE_N, pipe);
80	        wsQueue_.InitFreeSlots();
81	    }
82	}
83	
84	__aicore__ inline void GroupedMatmulSliceKPerTokenDequantKernel::Process()
85	{
86	    int mIdx = 0, nIdx = 0;
87	    while (sched_.HasNext()) {
88	        sched_.Next(mIdx, nIdx);
89	        if ASCEND_IS_AIC {
90	            auto slot = wsQueue_.ProducerAcquire();
91	            auto aBlock = aGM_[mIdx * BASE_M * tiling.K_pad];
92	            auto bBlock = bGM_[nIdx * BASE_N];
93	            mm_.ComputeBlock(aBlock, bBlock, slot);
94	            wsQueue_.ProducerRelease();
95	        }
96	        if ASCEND_IS_AIV {
97	            auto slot = wsQueue_.ConsumerAcquire();
98	            int rowOffset = AscendC::GetSubBlockIdx() * subTileM_;
99	            auto subSlot = slot[rowOffset * BASE_N];
100	            auto scaleBlock = scaleGM_[nIdx * BASE_N];
101	            auto ptScaleBlock = ptScaleGM_[mIdx * BASE_M + rowOffset];
102	            auto cBlock = cGM_[(mIdx * BASE_M + rowOffset) * tiling.N_pad + nIdx * BASE_N];
103	            dequantKernel_.Process(subSlot, scaleBlock, ptScaleBlock, cBlock, tiling.N_pad);
104	            wsQueue_.ConsumerRelease();
105	        }
106	    }
107	}
