6	#ifndef DEQUANT_KERNEL_H
7	#define DEQUANT_KERNEL_H
8	
9	#include "kernel_operator.h"
10	
11	using namespace AscendC;
12	
13	template <typename accType, typename outType>
14	class DequantKernel {
15	public:
16	    __aicore__ inline DequantKernel() {}
17	    __aicore__ inline void Init(int subBlockM, int blockN, AscendC::TPipe *pipe);
18	    __aicore__ inline void Process(GlobalTensor<accType> &slotGM,
19	                                   GlobalTensor<float> &scaleGM,
20	                                   GlobalTensor<float> &ptScaleGM,
21	                                   GlobalTensor<outType> &cGlobal, int rowStride);
22	private:
23	    int subBlockM_;
24	    int blockN_;
25	    int tileSize_;
26	
27	    AscendC::LocalTensor<accType> inLocal_;
28	    AscendC::LocalTensor<outType> outLocal_;
29	
30	    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
31	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
32	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;   // float32 [subBlockM, blockN]
33	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;  // float32 [blockN]
34	    AscendC::TBuf<AscendC::TPosition::VECCALC> ptScaleBuf_;// float32 [subBlockM]
35	};
36	
37	template <typename accType, typename outType>
38	__aicore__ inline void DequantKernel<accType, outType>::Init(int subBlockM, int blockN, AscendC::TPipe *pipe)
39	{
40	    subBlockM_ = subBlockM;
41	    blockN_ = blockN;
42	    tileSize_ = subBlockM * blockN;
43	
44	    pipe->InitBuffer(inQueue_, 1, tileSize_ * sizeof(accType));
45	    pipe->InitBuffer(outQueue_, 1, tileSize_ * sizeof(outType));
46	    pipe->InitBuffer(castBuf_, tileSize_ * sizeof(float));
47	    pipe->InitBuffer(scaleBuf_, blockN * sizeof(float));
48	    pipe->InitBuffer(ptScaleBuf_, subBlockM * sizeof(float));
49	}
50	
51	template <typename accType, typename outType>
52	__aicore__ inline void DequantKernel<accType, outType>::Process(
53	    GlobalTensor<accType> &slotGM,
54	    GlobalTensor<float> &scaleGM,
55	    GlobalTensor<float> &ptScaleGM,
56	    GlobalTensor<outType> &cGlobal, int rowStride)
57	{
58	    // CopyIn: workspace slot → VECIN
59	    inQueue_.AllocTensor<accType>(inLocal_);
60	    AscendC::DataCopy(inLocal_, slotGM, tileSize_);
61	    inQueue_.EnQue(inLocal_);
62	
63	    // CopyIn: per-column scale → TBuf (manual sync)
64	    AscendC::LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
65	    AscendC::DataCopy(scaleLocal, scaleGM, blockN_);
66	
67	    // CopyIn: per-token scale → TBuf (manual sync)
68	    AscendC::LocalTensor<float> ptScaleLocal = ptScaleBuf_.Get<float>();
69	    AscendC::DataCopy(ptScaleLocal, ptScaleGM, subBlockM_);
70	    PipeBarrier<PIPE_MTE2>();
71	
72	    // Compute: DeQue int32 → Cast int32→fp32
73	    inQueue_.DeQue<accType>(inLocal_);
74	    AscendC::LocalTensor<float> fp32Local = castBuf_.Get<float>();
75	    AscendC::Cast(fp32Local, inLocal_, AscendC::RoundMode::CAST_NONE, tileSize_);
76	    PipeBarrier<PIPE_V>();
77	
78	    // Per-row multiply by per-column scale
79	    for (int i = 0; i < subBlockM_; i++) {
80	        AscendC::Mul(fp32Local[i * blockN_], fp32Local[i * blockN_], scaleLocal, blockN_);
81	    }
82	    PipeBarrier<PIPE_V>();
83	
84	    // Per-row multiply by per-token scale (scalar Muls per row)
85	    for (int i = 0; i < subBlockM_; i++) {
86	        float ptVal = ptScaleLocal.GetValue(i);
87	        AscendC::Muls(fp32Local[i * blockN_], fp32Local[i * blockN_], ptVal, blockN_);
88	    }
89	    PipeBarrier<PIPE_V>();
90	
91	    // Cast fp32→outType → VECOUT
92	    outQueue_.AllocTensor<outType>(outLocal_);
93	    AscendC::Cast(outLocal_, fp32Local, AscendC::RoundMode::CAST_NONE, tileSize_);
94	
95	    inQueue_.FreeTensor(inLocal_);
96	    outQueue_.EnQue(outLocal_);
97	
98	    // CopyOut
99	    outQueue_.DeQue<outType>(outLocal_);
100	    AscendC::DataCopyParams copyParam = {
101	        (uint16_t)subBlockM_,
102	        (uint16_t)(blockN_ * sizeof(outType) / AscendC::DEFAULT_C0_SIZE),
103	        0,
104	        (uint16_t)((rowStride - blockN_) * sizeof(outType) / AscendC::DEFAULT_C0_SIZE)
105	    };
106	    AscendC::DataCopy(cGlobal, outLocal_, copyParam);
107	    outQueue_.FreeTensor(outLocal_);
108	}
109	
110	#endif // DEQUANT_KERNEL_H
