/**
 * @file quant_matmul.h
 *
 * Top-level kernel orchestrator for QuantMatmul.
 * AIC (Cube):  int8 matmul -> workspace (int32)
 * AIV (Vector): workspace -> Cast(int32->fp32) -> Mul(scale[N])
 *               -> Mul(per_token_scale[M]) -> output(fp32)
 */
#pragma once

#ifndef K_MAX_SHAPE_DIM
#define K_MAX_SHAPE_DIM 0
#endif

#include "kernel_operator.h"
#include "workspace_queue.h"
#include "kernel_common.h"
#include "quant_matmul_tiling.h"
#include "dequant_kernel.h"
#include "matmul.h"

#define CUBE_NOTIFY_VECTOR_ID 0x8
#define VECTOR_NOTIFY_CUBE_ID 0x9

using namespace AscendC;

class QuantMatmulKernel {
public:
    __aicore__ inline QuantMatmulKernel() {}
    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
                                GM_ADDR c, GM_ADDR workspace, GM_ADDR tiling, AscendC::TPipe *pipe);
    __aicore__ inline void Process();

    MatmulKernel<int8_t, int8_t, int32_t> mm_;
    AscendC::GlobalTensor<int8_t> aGM_;
    AscendC::GlobalTensor<int8_t> bGM_;
    AscendC::GlobalTensor<float> scaleGM_;
    AscendC::GlobalTensor<float> ptScaleGM_;
    AscendC::GlobalTensor<float> cGM_;
    WorkspaceQueue<int32_t, WORKSPACE_DEPTH> wsQueue_;
    QuantMatmulTiling tiling;
    DequantKernel<int32_t> dequantKernel_;
    BlockScheduler sched_;
    int subTileM_;
};

__aicore__ inline void QuantMatmulKernel::Init(
    GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
    GM_ADDR c, GM_ADDR workspace, GM_ADDR tilingGM, AscendC::TPipe *pipe)
{
    CopyTiling(&this->tiling, tilingGM);

    // Use padded dimensions for computation
    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling.M_pad * tiling.K_pad);
    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling.K_pad * tiling.N_pad);
    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling.N_pad);
    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(perTokenScale), tiling.M_pad);
    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(c), tiling.M_pad * tiling.N_pad);

    int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
    sched_.Init(tiling.M_pad, tiling.N_pad, BASE_M, BASE_N,
                AscendC::GetBlockNum(), coreIdx);

    uint32_t wsOffset = coreIdx * WORKSPACE_DEPTH * BASE_M * BASE_N;
    wsQueue_.Init(workspace + wsOffset * sizeof(int32_t),
                  BASE_M * BASE_N,
                  CUBE_NOTIFY_VECTOR_ID, VECTOR_NOTIFY_CUBE_ID);

    if ASCEND_IS_AIC {
        mm_.Init(tiling.K_pad, tiling.K_pad, tiling.N_pad, *pipe);
    }

    if ASCEND_IS_AIV {
        subTileM_ = BASE_M / AscendC::GetSubBlockNum();
        dequantKernel_.Init(subTileM_, BASE_N, pipe);
        wsQueue_.InitFreeSlots();
    }
}

__aicore__ inline void QuantMatmulKernel::Process()
{
    int mIdx = 0, nIdx = 0;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);
        if ASCEND_IS_AIC {
            auto slot = wsQueue_.ProducerAcquire();
            auto aBlock = aGM_[mIdx * BASE_M * tiling.K_pad];
            auto bBlock = bGM_[nIdx * BASE_N];
            mm_.ComputeBlock(aBlock, bBlock, slot);
            wsQueue_.ProducerRelease();
        }
        if ASCEND_IS_AIV {
            auto slot = wsQueue_.ConsumerAcquire();
            int rowOffset = AscendC::GetSubBlockIdx() * subTileM_;
            auto subSlot = slot[rowOffset * BASE_N];
            auto scaleBlock = scaleGM_[nIdx * BASE_N];
            auto ptScaleBlock = ptScaleGM_[mIdx * BASE_M + rowOffset];
            auto cBlock = cGM_[(mIdx * BASE_M + rowOffset) * tiling.N_pad + nIdx * BASE_N];
            dequantKernel_.Process(subSlot, scaleBlock, ptScaleBlock, cBlock);
            wsQueue_.ConsumerRelease();
        }
    }
}
