13	/**
14	 * DequantKernel for QuantMatmul.
15	 *
16	 * AIV (Vector): workspace(itemSize=int32) -> Cast(int32->fp32) -> Mul(scale[N])
17	 *               -> Mul(per_token_scale[M]) -> output(fp32)
18	 */
19	template <typename accType>
20	class DequantKernel {
21	public:
22	    __aicore__ inline DequantKernel() {}
23	    __aicore__ inline void Init(int subBlockM, int blockN, AscendC::TPipe *pipe);
24	    __aicore__ inline void Process(GlobalTensor<accType> &slotGM,
25	                                   GlobalTensor<float> &scaleGM,
26	                                   GlobalTensor<float> &ptScaleGM,
27	                                   GlobalTensor<float> &cGlobal);
28	
29	private:
30	    int subBlockM_;
31	    int blockN_;
32	    int tileSize_;
33	
34	    AscendC::LocalTensor<accType> inLocal_;
35	    AscendC::LocalTensor<float> outLocal_;
36	
37	    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
38	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
39	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;    // float32 [subBlockM, blockN]
40	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;   // float32 [blockN]
41	    AscendC::TBuf<AscendC::TPosition::VECCALC> ptScaleBuf_; // float32 [subBlockM]
42	};
43	
44	template <typename accType>
45	__aicore__ inline void DequantKernel<accType>::Init(int subBlockM, int blockN, AscendC::TPipe *pipe)
46	{
47	    subBlockM_ = subBlockM;
48	    blockN_ = blockN;
49	    tileSize_ = subBlockM * blockN;
50	
51	    pipe->InitBuffer(inQueue_, 1, tileSize_ * sizeof(accType));
52	    pipe->InitBuffer(outQueue_, 1, tileSize_ * sizeof(float));
53	    pipe->InitBuffer(castBuf_, tileSize_ * sizeof(float));
54	    pipe->InitBuffer(scaleBuf_, blockN * sizeof(float));
55	    pipe->InitBuffer(ptScaleBuf_, subBlockM * sizeof(float));
56	}
57	
58	template <typename accType>
59	__aicore__ inline void DequantKernel<accType>::Process(
60	    GlobalTensor<accType> &slotGM,
61	    GlobalTensor<float> &scaleGM,
62	    GlobalTensor<float> &ptScaleGM,
63	    GlobalTensor<float> &cGlobal)
64	{
65	    // CopyIn: workspace slot (int32) -> VECIN
66	    inQueue_.AllocTensor<accType>(inLocal_);
67	    AscendC::DataCopy(inLocal_, slotGM, tileSize_);
