#ifndef DEQUANT_KERNEL_H
#define DEQUANT_KERNEL_H

#include "kernel_operator.h"

using namespace AscendC;

/**
 * DequantKernel for QuantMatmul.
 *
 * AIV (Vector): workspace(itemSize=int32) -> Cast(int32->fp32) -> Mul(scale[N])
 *               -> Mul(per_token_scale[M]) -> output(fp32)
 *
 * The output matrix may have a row stride (N_pad) that differs from blockN.
 * DataCopyParams is used to write each row of the tile at the correct stride.
 */
template <typename accType>
class DequantKernel {
public:
    __aicore__ inline DequantKernel() {}
    __aicore__ inline void Init(int subBlockM, int blockN, AscendC::TPipe *pipe);
    __aicore__ inline void Process(GlobalTensor<accType> &slotGM,
                                   GlobalTensor<float> &scaleGM,
                                   GlobalTensor<float> &ptScaleGM,
                                   GlobalTensor<float> &cGlobal,
                                   int rowStride);

private:
    int subBlockM_;
    int blockN_;
    int tileSize_;

    AscendC::LocalTensor<accType> inLocal_;
    AscendC::LocalTensor<float> outLocal_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;    // float32 [subBlockM, blockN]
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;   // float32 [blockN]
    AscendC::TBuf<AscendC::TPosition::VECCALC> ptScaleBuf_; // float32 [subBlockM]
};

template <typename accType>
__aicore__ inline void DequantKernel<accType>::Init(int subBlockM, int blockN, AscendC::TPipe *pipe)
{
    subBlockM_ = subBlockM;
    blockN_ = blockN;
    tileSize_ = subBlockM * blockN;

    pipe->InitBuffer(inQueue_, 1, tileSize_ * sizeof(accType));
    pipe->InitBuffer(outQueue_, 1, tileSize_ * sizeof(float));
    pipe->InitBuffer(castBuf_, tileSize_ * sizeof(float));
    pipe->InitBuffer(scaleBuf_, blockN * sizeof(float));
    pipe->InitBuffer(ptScaleBuf_, subBlockM * sizeof(float));
}

template <typename accType>
__aicore__ inline void DequantKernel<accType>::Process(
    GlobalTensor<accType> &slotGM,
    GlobalTensor<float> &scaleGM,
    GlobalTensor<float> &ptScaleGM,
    GlobalTensor<float> &cGlobal,
    int rowStride)
{
    // CopyIn: workspace slot (int32) -> VECIN
    inQueue_.AllocTensor<accType>(inLocal_);
    AscendC::DataCopy(inLocal_, slotGM, tileSize_);
    inQueue_.EnQue(inLocal_);

    // CopyIn: per-column scale -> TBuf (manual sync)
    AscendC::LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
    AscendC::DataCopy(scaleLocal, scaleGM, blockN_);

    // CopyIn: per-token scale -> TBuf (manual sync)
    AscendC::LocalTensor<float> ptScaleLocal = ptScaleBuf_.Get<float>();
    AscendC::DataCopy(ptScaleLocal, ptScaleGM, subBlockM_);
    PipeBarrier<PIPE_MTE2>();

    // Compute: DeQue int32 -> Cast int32->fp32
    inQueue_.DeQue<accType>(inLocal_);
    AscendC::LocalTensor<float> fp32Local = castBuf_.Get<float>();
    AscendC::Cast(fp32Local, inLocal_, AscendC::RoundMode::CAST_NONE, tileSize_);
    PipeBarrier<PIPE_V>();

    // Per-row multiply by per-column scale
    for (int i = 0; i < subBlockM_; i++) {
        AscendC::Mul(fp32Local[i * blockN_], fp32Local[i * blockN_], scaleLocal, blockN_);
    }
    PipeBarrier<PIPE_V>();

    // Per-row multiply by per-token scale (scalar Muls per row)
    for (int i = 0; i < subBlockM_; i++) {
        float ptVal = ptScaleLocal.GetValue(i);
        AscendC::Muls(fp32Local[i * blockN_], fp32Local[i * blockN_], ptVal, blockN_);
    }
    PipeBarrier<PIPE_V>();

    // Copy fp32 result -> VECOUT for CopyOut to GM
    outQueue_.AllocTensor<float>(outLocal_);
    AscendC::DataCopy(outLocal_, fp32Local, tileSize_);

    inQueue_.FreeTensor(inLocal_);
    outQueue_.EnQue(outLocal_);

    // CopyOut: VECOUT -> GM using DataCopyParams with row stride
    outQueue_.DeQue<float>(outLocal_);
    AscendC::DataCopyParams copyParam = {
        (uint16_t)subBlockM_,
        (uint16_t)(blockN_ * sizeof(float) / AscendC::DEFAULT_C0_SIZE),
        0,
        (uint16_t)((rowStride - blockN_) * sizeof(float) / AscendC::DEFAULT_C0_SIZE)
    };
    AscendC::DataCopy(cGlobal, outLocal_, copyParam);
    outQueue_.FreeTensor(outLocal_);
}

#endif // DEQUANT_KERNEL_H
