53	    GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
54	    GM_ADDR c, GM_ADDR workspace, GM_ADDR tilingGM, AscendC::TPipe *pipe)
55	{
56	    CopyTiling(&this->tiling, tilingGM);
57	
58	    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling.M * tiling.K);
59	    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling.K * tiling.N);
60	    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling.N);
61	    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(perTokenScale), tiling.M);
62	    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ bfloat16_t *>(c), tiling.M * tiling.N);
63	
64	    int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
65	    sched_.Init(tiling.M, tiling.N, tiling.baseM, tiling.baseN,
66	                AscendC::GetBlockNum(), coreIdx);
67	
68	    uint32_t wsOffset = coreIdx * WORKSPACE_DEPTH * tiling.baseM * tiling.baseN;
69	    wsQueue_.Init(workspace + wsOffset * sizeof(int32_t),
70	                  tiling.baseM * tiling.baseN,
71	                  CUBE_NOTIFY_VECTOR_ID, VECTOR_NOTIFY_CUBE_ID);
72	
73	    if ASCEND_IS_AIC {
74	        mm_.Init(tiling.K, tiling.K, tiling.N, *pipe);
75	    }
76	
77	    if ASCEND_IS_AIV {
78	        subTileM_ = tiling.baseM / AscendC::GetSubBlockNum();
79	        scaleKernel_.Init(subTileM_, tiling.baseN, pipe);
80	        wsQueue_.InitFreeSlots();
81	    }
82	}
