84	__aicore__ inline void GroupedMatmulSliceKPerTokenDequantKernel::Process()
85	{
86	    int mIdx = 0, nIdx = 0;
87	    while (sched_.HasNext()) {
88	        sched_.Next(mIdx, nIdx);
89	        if ASCEND_IS_AIC {
90	            auto slot = wsQueue_.ProducerAcquire();
91	            auto aBlock = aGM_[mIdx * tiling.baseM * tiling.K];
92	            auto bBlock = bGM_[nIdx * tiling.baseN];
93	            mm_.ComputeBlock(aBlock, bBlock, slot);
94	            wsQueue_.ProducerRelease();
95	        }
96	        if ASCEND_IS_AIV {
97	            auto slot = wsQueue_.ConsumerAcquire();
98	            int rowOffset = AscendC::GetSubBlockIdx() * subTileM_;
99	            auto subSlot = slot[rowOffset * tiling.baseN];
100	            auto scaleBlock = scaleGM_[nIdx * tiling.baseN];
101	            auto ptScaleBlock = ptScaleGM_[mIdx * tiling.baseM + rowOffset];
102	            auto cBlock = cGM_[(mIdx * tiling.baseM + rowOffset) * tiling.N + nIdx * tiling.baseN];
103	            scaleKernel_.Process(subSlot, scaleBlock, ptScaleBlock, cBlock, tiling.N);
104	            wsQueue_.ConsumerRelease();
105	        }
106	    }
107	}
