#ifndef QUANT_MATMUL_MATMUL_H
#define QUANT_MATMUL_MATMUL_H

#include "kernel_operator.h"
#include "matmul.h"
#include "quant_matmul_tiling.h"

using namespace AscendC;

class QuantMatmulMatmulKernel {
public:
    __aicore__ inline QuantMatmulMatmulKernel() {}
    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tiling, AscendC::TPipe *pipe);
    __aicore__ inline void Process();

    MatmulKernel<int8_t, int8_t, int32_t> mm_;
    AscendC::GlobalTensor<int8_t> aGM_;
    AscendC::GlobalTensor<int8_t> bGM_;
    AscendC::GlobalTensor<int32_t> cGM_;
    QuantMatmulTiling tiling_;
    BlockScheduler sched_;
};

__aicore__ inline void QuantMatmulMatmulKernel::Init(
    GM_ADDR a, GM_ADDR b, GM_ADDR c,
    GM_ADDR tilingGM, AscendC::TPipe *pipe)
{
    CopyTiling(&tiling_, tilingGM);

    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling_.M_pad * tiling_.K_pad);
    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling_.K_pad * tiling_.N_pad);
    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(c), tiling_.M_pad * tiling_.N_pad);

    int coreIdx = GetBlockIdx();
    sched_.Init(tiling_.M_pad, tiling_.N_pad, BASE_M, BASE_N,
                GetBlockNum(), coreIdx);

    mm_.Init(tiling_.K_pad, tiling_.K_pad, tiling_.N_pad, *pipe);
}

__aicore__ inline void QuantMatmulMatmulKernel::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);

        int rowStart = mIdx * BASE_M;
        int colStart = nIdx * BASE_N;

        auto aBlock = aGM_[rowStart * tiling_.K_pad];
        auto bBlock = bGM_[colStart];
        auto cBlock = cGM_[rowStart * tiling_.N_pad + colStart];

        mm_.ComputeBlock(aBlock, bBlock, cBlock);
    }
}

#endif // QUANT_MATMUL_MATMUL_H
