#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_quant_matmul_matmul.h"
#include "aclrtlaunch_quant_matmul_dequant.h"
#include "quant_matmul_tiling.h"

#include <algorithm>

namespace ascend_kernel {

static int32_t AlignUp(int32_t val, int32_t alignment)
{
    return ((val + alignment - 1) / alignment) * alignment;
}

at::Tensor quant_matmul(
    const at::Tensor &a, const at::Tensor &b,
    const at::Tensor &scale, const at::Tensor &per_token_scale)
{
    TORCH_CHECK(a.dim() == 2, "a must be 2D");
    TORCH_CHECK(b.dim() == 2, "b must be 2D");
    TORCH_CHECK(scale.dim() == 1, "scale must be 1D [N]");
    TORCH_CHECK(per_token_scale.dim() == 1, "per_token_scale must be 1D [M]");
    TORCH_CHECK(a.sizes()[0] == per_token_scale.sizes()[0], "M dimension mismatch");
    TORCH_CHECK(b.sizes()[1] == scale.sizes()[0], "N dimension mismatch");
    TORCH_CHECK(a.sizes()[1] == b.sizes()[0], "K dimension mismatch");
    TORCH_CHECK(a.scalar_type() == at::kChar, "a must be int8");
    TORCH_CHECK(b.scalar_type() == at::kChar, "b must be int8");

    at::Tensor a_contig = a.contiguous();
    at::Tensor b_contig = b.contiguous();

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t usedCoreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    int32_t m = static_cast<int32_t>(a_contig.sizes()[0]);
    int32_t k = static_cast<int32_t>(a_contig.sizes()[1]);
    int32_t n = static_cast<int32_t>(b_contig.sizes()[1]);

    int32_t k_l1 = L1_PREFETCH * BASE_K;

    // Pad dimensions
    int32_t m_pad = AlignUp(m, BASE_M);
    int32_t n_pad = AlignUp(n, BASE_N);
    int32_t k_pad = AlignUp(k, k_l1);

    // Create padded A [m_pad, k_pad]
    at::Tensor a_pad = at::zeros({static_cast<int64_t>(m_pad), static_cast<int64_t>(k_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kChar));
    at::Tensor a_view = a_pad.slice(1, 0, k).slice(0, 0, m);
    a_view.copy_(a_contig);

    // Create padded B [k_pad, n_pad]
    at::Tensor b_pad = at::zeros({static_cast<int64_t>(k_pad), static_cast<int64_t>(n_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kChar));
    at::Tensor b_view = b_pad.slice(0, 0, k).slice(1, 0, n);
    b_view.copy_(b_contig);

    // Padded scale [n_pad] (float32)
    at::Tensor scale_fp32 = scale.to(at::kFloat).contiguous();
    at::Tensor scale_pad = at::zeros({static_cast<int64_t>(n_pad)},
                                      at::device(at::kPrivateUse1).dtype(at::kFloat));
    scale_pad.slice(0, 0, n).copy_(scale_fp32);

    // Padded per_token_scale [m_pad] (float32)
    at::Tensor pt_scale_fp32 = per_token_scale.to(at::kFloat).contiguous();
    at::Tensor pt_scale_pad = at::zeros({static_cast<int64_t>(m_pad)},
                                         at::device(at::kPrivateUse1).dtype(at::kFloat));
    pt_scale_pad.slice(0, 0, m).copy_(pt_scale_fp32);

    // Workspace for int32 matmul result [m_pad, n_pad]
    at::Tensor workspace = at::empty({static_cast<int64_t>(m_pad), static_cast<int64_t>(n_pad)},
                                      at::device(at::kPrivateUse1).dtype(at::kInt));

    // Output [m_pad, n_pad] float32
    at::Tensor c_pad = at::empty({static_cast<int64_t>(m_pad), static_cast<int64_t>(n_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kFloat));

    // Tiling data for both kernels
    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(QuantMatmulTiling))},
                             at::device(at::kCPU).dtype(at::kByte));
    auto *tiling_ptr = reinterpret_cast<QuantMatmulTiling *>(t.data_ptr());
    tiling_ptr->M = m;
    tiling_ptr->N = n;
    tiling_ptr->K = k;
    tiling_ptr->M_pad = m_pad;
    tiling_ptr->N_pad = n_pad;
    tiling_ptr->K_pad = k_pad;
    auto tiling_npu = t.to(at::kPrivateUse1);

    // --- Kernel 1: Matmul (AIC) ---
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    EXEC_KERNEL_CMD(quant_matmul_matmul, blockDim,
                    a_pad, b_pad, workspace, tiling_npu);

    // --- Kernel 2: Dequant (AIV) ---
    EXEC_KERNEL_CMD(quant_matmul_dequant, blockDim,
                    workspace, scale_pad, pt_scale_pad, c_pad, tiling_npu);

    // Trim output to [m, n]
    at::Tensor c_valid = c_pad.slice(0, 0, m).slice(1, 0, n);
    return c_valid.contiguous();
}

} // namespace ascend_kernel
