#ifndef QUANT_MATMUL_DEQUANT_H
#define QUANT_MATMUL_DEQUANT_H

#include "kernel_operator.h"
#include "kernel_common.h"
#include "quant_matmul_tiling.h"

using namespace AscendC;

constexpr int SUB_TILE_M = 64;
constexpr int SUB_TILE_N = 64;

class QuantMatmulDequantKernel {
public:
    __aicore__ inline QuantMatmulDequantKernel() {}
    __aicore__ inline void Init(GM_ADDR src, GM_ADDR scale, GM_ADDR ptScale,
                                GM_ADDR dst, GM_ADDR tiling, AscendC::TPipe *pipe);
    __aicore__ inline void Process();

    AscendC::GlobalTensor<int32_t> srcGM_;
    AscendC::GlobalTensor<float> scaleGM_;
    AscendC::GlobalTensor<float> ptScaleGM_;
    AscendC::GlobalTensor<float> dstGM_;
    QuantMatmulTiling tiling_;
    BlockScheduler sched_;

    int subTileSize_;

    AscendC::LocalTensor<int32_t> inLocal_;
    AscendC::LocalTensor<float> outLocal_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ptScaleBuf_;
};

__aicore__ inline void QuantMatmulDequantKernel::Init(
    GM_ADDR src, GM_ADDR scale, GM_ADDR ptScale,
    GM_ADDR dst, GM_ADDR tilingGM, AscendC::TPipe *pipe)
{
    CopyTiling(&tiling_, tilingGM);

    srcGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(src), tiling_.M_pad * tiling_.N_pad);
    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling_.N_pad);
    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(ptScale), tiling_.M_pad);
    dstGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dst), tiling_.M_pad * tiling_.N_pad);

    subTileSize_ = SUB_TILE_M * SUB_TILE_N;

    int coreIdx = GetBlockIdx();
    sched_.Init(tiling_.M_pad, tiling_.N_pad, BASE_M, BASE_N,
                GetBlockNum(), coreIdx);

    pipe->InitBuffer(inQueue_, 1, subTileSize_ * sizeof(int32_t));
    pipe->InitBuffer(outQueue_, 1, subTileSize_ * sizeof(float));
    pipe->InitBuffer(castBuf_, subTileSize_ * sizeof(float));
    pipe->InitBuffer(scaleBuf_, SUB_TILE_N * sizeof(float));
    pipe->InitBuffer(ptScaleBuf_, SUB_TILE_M * sizeof(float));
}

__aicore__ inline void QuantMatmulDequantKernel::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);

        int mBase = mIdx * BASE_M;
        int nBase = nIdx * BASE_N;

        // Process 128x128 block in 64x64 sub-tiles
        for (int sm = 0; sm < BASE_M; sm += SUB_TILE_M) {
            for (int sn = 0; sn < BASE_N; sn += SUB_TILE_N) {
                int rowStart = mBase + sm;
                int colStart = nBase + sn;

                auto srcBlock = srcGM_[rowStart * tiling_.N_pad + colStart];
                auto scaleBlock = scaleGM_[colStart];
                auto ptScaleBlock = ptScaleGM_[rowStart];
                auto dstBlock = dstGM_[rowStart * tiling_.N_pad + colStart];

                // CopyIn: int32 -> VECIN (depth-0)
                inQueue_.AllocTensor(inLocal_);
                AscendC::DataCopy(inLocal_, srcBlock, subTileSize_);
                inQueue_.EnQue(inLocal_);

                // Load scale -> TBuf
                AscendC::LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
                AscendC::DataCopy(scaleLocal, scaleBlock, SUB_TILE_N);

                // Load pt_scale -> TBuf
                AscendC::LocalTensor<float> ptScaleLocal = ptScaleBuf_.Get<float>();
                AscendC::DataCopy(ptScaleLocal, ptScaleBlock, SUB_TILE_M);
                PipeBarrier<PIPE_MTE2>();

                // DeQue int32 -> Cast to fp32
                inQueue_.DeQue(inLocal_);
                AscendC::LocalTensor<float> fp32Local = castBuf_.Get<float>();
                AscendC::Cast(fp32Local, inLocal_, AscendC::RoundMode::CAST_NONE, subTileSize_);
                PipeBarrier<PIPE_V>();

                // Row-wise mul by column scale
                for (int i = 0; i < SUB_TILE_M; i++) {
                    AscendC::Mul(fp32Local[i * SUB_TILE_N], fp32Local[i * SUB_TILE_N],
                                 scaleLocal, SUB_TILE_N);
                }
                PipeBarrier<PIPE_V>();

                // Row-wise mul by per-token scale
                for (int i = 0; i < SUB_TILE_M; i++) {
                    float ptVal = ptScaleLocal.GetValue(i);
                    AscendC::Muls(fp32Local[i * SUB_TILE_N], fp32Local[i * SUB_TILE_N],
                                  ptVal, SUB_TILE_N);
                }
                PipeBarrier<PIPE_V>();

                // Copy result -> VECOUT
                outQueue_.AllocTensor(outLocal_);
                AscendC::DataCopy(outLocal_, fp32Local, subTileSize_);
                inQueue_.FreeTensor(inLocal_);
                outQueue_.EnQue(outLocal_);

                // CopyOut to GM
                outQueue_.DeQue(outLocal_);
                AscendC::DataCopyParams copyParam = {
                    (uint16_t)SUB_TILE_M,
                    (uint16_t)(SUB_TILE_N * sizeof(float) / AscendC::DEFAULT_C0_SIZE),
                    0,
                    (uint16_t)((tiling_.N_pad - SUB_TILE_N) * sizeof(float) / AscendC::DEFAULT_C0_SIZE)
                };
                AscendC::DataCopy(dstBlock, outLocal_, copyParam);
                outQueue_.FreeTensor(outLocal_);
            }
        }
    }
}

