6	/**
7	 * @file scale_kernel.h
8	 *
9	 * Vector kernel: Cast(int32->fp32) -> per-row Mul(scale[N]) -> per-row Muls(ptScale[M])
10	 *                -> Cast(fp32->fp16) -> output.
11	 */
12	#ifndef SCALE_KERNEL_H
13	#define SCALE_KERNEL_H
14	
15	#include "kernel_operator.h"
16	
17	using namespace AscendC;
18	
19	template <typename accType, typename outType>
20	class ScaleKernel {
21	public:
22	    __aicore__ inline ScaleKernel() {}
23	    __aicore__ inline void Init(int subBlockM, int blockN, AscendC::TPipe *pipe);
24	    __aicore__ inline void Process(GlobalTensor<accType> &slotGM,
25	                                   GlobalTensor<float> &scaleGM,
26	                                   GlobalTensor<float> &ptScaleGM,
27	                                   GlobalTensor<outType> &cGlobal, int rowStride);
28	private:
29	    int subBlockM_;
30	    int blockN_;
31	    int tileSize_;
32	
33	    AscendC::LocalTensor<accType> inLocal_;
34	    AscendC::LocalTensor<outType> outLocal_;
35	
36	    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
37	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
38	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;    // float32 intermediate [subBlockM, blockN]
39	    AscendC::TBuf<AscendC::TPosition::VECCALC> scaleBuf_;   // float32 scale vector [blockN]
40	    AscendC::TBuf<AscendC::TPosition::VECCALC> ptScaleBuf_; // float32 per-token scale [subBlockM]
41	};
42	
43	template <typename accType, typename outType>
44	__aicore__ inline void ScaleKernel<accType, outType>::Init(int subBlockM, int blockN, AscendC::TPipe *pipe)
45	{
46	    subBlockM_ = subBlockM;
47	    blockN_ = blockN;
48	    tileSize_ = subBlockM * blockN;
49	
50	    pipe->InitBuffer(inQueue_, 1, tileSize_ * sizeof(accType));
51	    pipe->InitBuffer(outQueue_, 1, tileSize_ * sizeof(outType));
52	    pipe->InitBuffer(castBuf_, tileSize_ * sizeof(float));
53	    pipe->InitBuffer(scaleBuf_, blockN * sizeof(float));
54	    pipe->InitBuffer(ptScaleBuf_, subBlockM * sizeof(float));
55	}
56	
57	template <typename accType, typename outType>
58	__aicore__ inline void ScaleKernel<accType, outType>::Process(
59	    GlobalTensor<accType> &slotGM,
60	    GlobalTensor<float> &scaleGM,
61	    GlobalTensor<float> &ptScaleGM,
62	    GlobalTensor<outType> &cGlobal, int rowStride)
63	{
64	    // CopyIn: workspace slot -> inQueue
65	    inQueue_.AllocTensor<accType>(inLocal_);
66	    AscendC::DataCopy(inLocal_, slotGM, tileSize_);
67	    inQueue_.EnQue(inLocal_);
68	
69	    // Load scale vector -> scaleBuf (TBuf, manual sync)
70	    AscendC::LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
71	    AscendC::DataCopy(scaleLocal, scaleGM, blockN_);
72	
73	    // Load per-token scale -> ptScaleBuf (TBuf, manual sync)
74	    AscendC::LocalTensor<float> ptScaleLocal = ptScaleBuf_.Get<float>();
75	    AscendC::DataCopy(ptScaleLocal, ptScaleGM, subBlockM_);
76	    PipeBarrier<PIPE_MTE2>();
77	
78	    // Compute: Cast(int32->fp32) -> per-row Mul(scale) -> per-row Muls(ptScale)
79	    inQueue_.DeQue<accType>(inLocal_);
80	    AscendC::LocalTensor<float> fp32Local = castBuf_.Get<float>();
81	
82	    // int32 -> float32
83	    AscendC::Cast(fp32Local, inLocal_, AscendC::RoundMode::CAST_NONE, tileSize_);
84	    PipeBarrier<PIPE_V>();
85	
86	    // Per-row multiply by scale vector
87	    for (int i = 0; i < subBlockM_; i++) {
88	        AscendC::Mul(fp32Local[i * blockN_], fp32Local[i * blockN_], scaleLocal, blockN_);
89	    }
90	    PipeBarrier<PIPE_V>();
91	
92	    // Per-row multiply by per-token scale (scalar Muls)
93	    for (int i = 0; i < subBlockM_; i++) {
94	        float ptVal = ptScaleLocal.GetValue(i);
95	        AscendC::Muls(fp32Local[i * blockN_], fp32Local[i * blockN_], ptVal, blockN_);
96	    }
97	    PipeBarrier<PIPE_V>();
98	
99	    // float32 -> fp16
100	    outQueue_.AllocTensor<outType>(outLocal_);
101	    AscendC::Cast(outLocal_, fp32Local, AscendC::RoundMode::CAST_NONE, tileSize_);
102	
103	    inQueue_.FreeTensor(inLocal_);
104	    outQueue_.EnQue(outLocal_);
105	
106	    // CopyOut
107	    outQueue_.DeQue<outType>(outLocal_);
108	    AscendC::DataCopyParams copyParam = {
109	        (uint16_t)subBlockM_,
110	        (uint16_t)(blockN_ * sizeof(outType) / AscendC::DEFAULT_C0_SIZE),
111	        0,
112	        (uint16_t)((rowStride - blockN_) * sizeof(outType) / AscendC::DEFAULT_C0_SIZE)
113	    };
114	    AscendC::DataCopy(cGlobal, outLocal_, copyParam);
115	    outQueue_.FreeTensor(outLocal_);
116	}
117	
118	#endif // SCALE_KERNEL_H
