7	 * @file int8_matmul_scale.h
8	 *
9	 * Top-level kernel orchestrator for Int8 MatMul + Scale + Per-Token Scale.
10	 * AIC (Cube): int8 matmul -> workspace (int32)
11	 * AIV (Vector): Cast(int32->fp32) -> Mul(scale) -> per-row Muls(ptScale) -> Cast(fp32->fp16) -> output
12	 */
