27	#define VECTOR_NOTIFY_CUBE_ID 0x9
28	
29	using namespace AscendC;
30	
31	class Int8MatmulScaleKernel {
32	public:
33	    __aicore__ inline Int8MatmulScaleKernel() {}
34	    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
35	                                GM_ADDR c, GM_ADDR workspace, GM_ADDR tiling, AscendC::TPipe *pipe);
36	    __aicore__ inline void Process();
37	
38	    MatmulKernel<int8_t, int8_t, int32_t> mm_;
39	    AscendC::GlobalTensor<int8_t> aGM_;
40	    AscendC::GlobalTensor<int8_t> bGM_;
41	    AscendC::GlobalTensor<float> scaleGM_;
42	    AscendC::GlobalTensor<float> ptScaleGM_;
43	    AscendC::GlobalTensor<half> cGM_;
44	    WorkspaceQueue<int32_t, WORKSPACE_DEPTH> wsQueue_;
45	    Int8MatmulScaleTiling tiling;
46	    ScaleKernel<int32_t, half> scaleKernel_;
47	    BlockScheduler sched_;
48	    int subTileM_;
49	};
50	
51	__aicore__ inline void Int8MatmulScaleKernel::Init(GM_ADDR a, GM_ADDR b, GM_ADDR scale, GM_ADDR perTokenScale,
52	                                                    GM_ADDR c, GM_ADDR workspace, GM_ADDR tilingGM,
53	                                                    AscendC::TPipe *pipe)
54	{
55	    CopyTiling(&this->tiling, tilingGM);
56	
57	    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling.M * tiling.K);
58	    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling.K * tiling.N);
59	    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling.N);
60	    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(perTokenScale), tiling.M);
61	    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ half *>(c), tiling.M * tiling.N);
62	
63	    int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
64	    sched_.Init(tiling.M, tiling.N, tiling.baseM, tiling.baseN,
65	                AscendC::GetBlockNum(), coreIdx);
66	
67	    uint32_t wsOffset = coreIdx * WORKSPACE_DEPTH * tiling.baseM * tiling.baseN;
68	    wsQueue_.Init(workspace + wsOffset * sizeof(int32_t),
69	                  tiling.baseM * tiling.baseN,
70	                  CUBE_NOTIFY_VECTOR_ID, VECTOR_NOTIFY_CUBE_ID);
71	
72	    if ASCEND_IS_AIC {
73	        mm_.Init(tiling.K, tiling.K, tiling.N, *pipe);
74	    }
75	
76	    if ASCEND_IS_AIV {
77	        subTileM_ = tiling.baseM / AscendC::GetSubBlockNum();
78	        scaleKernel_.Init(subTileM_, tiling.baseN, pipe);
79	        wsQueue_.InitFreeSlots();
80	    }
81	}
82	
83	__aicore__ inline void Int8MatmulScaleKernel::Process()
84	{
85	    int mIdx = 0, nIdx = 0;
86	    while (sched_.HasNext()) {
87	        sched_.Next(mIdx, nIdx);
88	        if ASCEND_IS_AIC {
89	            auto slot = wsQueue_.ProducerAcquire();
90	            auto aBlock = aGM_[mIdx * tiling.baseM * tiling.K];
91	            auto bBlock = bGM_[nIdx * tiling.baseN];
92	            mm_.ComputeBlock(aBlock, bBlock, slot);
93	            wsQueue_.ProducerRelease();
94	        }
95	        if ASCEND_IS_AIV {
96	            auto slot = wsQueue_.ConsumerAcquire();
97	            int rowOffset = AscendC::GetSubBlockIdx() * subTileM_;
98	            auto subSlot = slot[rowOffset * tiling.baseN];
99	            auto scaleBlock = scaleGM_[nIdx * tiling.baseN];
100	            auto ptScaleBlock = ptScaleGM_[mIdx * tiling.baseM + rowOffset];
101	            auto cBlock = cGM_[(mIdx * tiling.baseM + rowOffset) * tiling.N + nIdx * tiling.baseN];
102	            scaleKernel_.Process(subSlot, scaleBlock, ptScaleBlock, cBlock, tiling.N);
103	            wsQueue_.ConsumerRelease();
104	        }
105	    }
106	}
