#ifndef QUANT_MATMUL_DEQUANT_H
#define QUANT_MATMUL_DEQUANT_H

#include "kernel_operator.h"
#include "kernel_common.h"
#include "quant_matmul_tiling.h"

using namespace AscendC;

class QuantMatmulDequantKernel {
public:
    __aicore__ inline QuantMatmulDequantKernel() {}
    __aicore__ inline void Init(GM_ADDR src, GM_ADDR scale, GM_ADDR ptScale, GM_ADDR dst,
                                GM_ADDR tiling, TPipe *pipe);
    __aicore__ inline void Process();

    GlobalTensor<int32_t> srcGM_;
    GlobalTensor<float> scaleGM_;
    GlobalTensor<float> ptScaleGM_;
    GlobalTensor<float> dstGM_;
    QuantMatmulTiling tiling_;
    BlockScheduler sched_;

    int subTileM_;
    int subTileN_;
    int subTileSize_;

    LocalTensor<int32_t> inLocal_;
    LocalTensor<float> outLocal_;

    TQue<TPosition::VECIN, 0> inQueue_;
    TQue<TPosition::VECOUT, 0> outQueue_;
    TBuf<TPosition::VECCALC> castBuf_;
    TBuf<TPosition::VECCALC> scaleBuf_;
    TBuf<TPosition::VECCALC> ptScaleBuf_;
};

__aicore__ inline void QuantMatmulDequantKernel::Init(
    GM_ADDR src, GM_ADDR scale, GM_ADDR ptScale,
    GM_ADDR dst, GM_ADDR tilingGM, TPipe *pipe)
{
    CopyTiling(&tiling_, tilingGM);

    srcGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(src), tiling_.M * tiling_.N);
    scaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(scale), tiling_.N);
    ptScaleGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(ptScale), tiling_.M);
    dstGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(dst), tiling_.M * tiling_.N);

    int coreIdx = GetBlockIdx();
    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN,
                GetBlockNum(), coreIdx);

    subTileM_ = 64;
    subTileN_ = 128;
    subTileSize_ = subTileM_ * subTileN_;

    pipe->InitBuffer(inQueue_, 1, subTileSize_ * sizeof(int32_t));
    pipe->InitBuffer(outQueue_, 1, subTileSize_ * sizeof(float));
    pipe->InitBuffer(castBuf_, subTileSize_ * sizeof(float));
    pipe->InitBuffer(scaleBuf_, subTileN_ * sizeof(float));
    pipe->InitBuffer(ptScaleBuf_, subTileM_ * sizeof(float));
}

__aicore__ inline void QuantMatmulDequantKernel::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);

        int baseRow = mIdx * tiling_.baseM;
        int baseCol = nIdx * tiling_.baseN;

        // Process baseM*baseN tile in sub-tiles
        for (int sm = 0; sm < tiling_.baseM; sm += subTileM_) {
            for (int sn = 0; sn < tiling_.baseN; sn += subTileN_) {
                int rowStart = baseRow + sm;
                int colStart = baseCol + sn;

                auto srcBlock = srcGM_[rowStart * tiling_.N + colStart];
                auto scaleBlock = scaleGM_[colStart];
                auto ptScaleBlock = ptScaleGM_[rowStart];
                auto dstBlock = dstGM_[rowStart * tiling_.N + colStart];

                // CopyIn int32 -> VECIN
                inQueue_.AllocTensor(inLocal_);
                DataCopy(inLocal_, srcBlock, subTileSize_);
                inQueue_.EnQue(inLocal_);

                // Load scale & pt_scale -> TBuf
                LocalTensor<float> scaleLocal = scaleBuf_.Get<float>();
                DataCopy(scaleLocal, scaleBlock, subTileN_);

                LocalTensor<float> ptScaleLocal = ptScaleBuf_.Get<float>();
                DataCopy(ptScaleLocal, ptScaleBlock, subTileM_);
                PipeBarrier<PIPE_MTE2>();

                // DeQue int32, Cast to fp32
                inQueue_.DeQue(inLocal_);
                LocalTensor<float> fp32Local = castBuf_.Get<float>();
                Cast(fp32Local, inLocal_, RoundMode::CAST_NONE, subTileSize_);
                PipeBarrier<PIPE_V>();

                // Row-wise mul by column scale
                for (int i = 0; i < subTileM_; i++) {
                    Mul(fp32Local[i * subTileN_], fp32Local[i * subTileN_], scaleLocal, subTileN_);
                }
                PipeBarrier<PIPE_V>();

                // Row-wise mul by per-token scale
                for (int i = 0; i < subTileM_; i++) {
                    float ptVal = ptScaleLocal.GetValue(i);
                    Muls(fp32Local[i * subTileN_], fp32Local[i * subTileN_], ptVal, subTileN_);
                }
                PipeBarrier<PIPE_V>();

                // Copy fp32 -> VECOUT
                outQueue_.AllocTensor(outLocal_);
                DataCopy(outLocal_, fp32Local, subTileSize_);
                inQueue_.FreeTensor(inLocal_);
                outQueue_.EnQue(outLocal_);

                // CopyOut with row stride
                outQueue_.DeQue(outLocal_);
                DataCopyParams copyParam = {
                    (uint16_t)subTileM_,
                    (uint16_t)(subTileN_ * sizeof(float) / DEFAULT_C0_SIZE),
                    0,
                    (uint16_t)((tiling_.N - subTileN_) * sizeof(float) / DEFAULT_C0_SIZE)
                };
                DataCopy(dstBlock, outLocal_, copyParam);
                outQueue_.FreeTensor(outLocal_);
            }
        }
    }
}
#endif
