{"content": "#pragma once
#include "kernel_operator.h"
#include "kernel_common.h"
#include "quant_matmul_tiling.h"
#include "matmul.h"

using namespace AscendC;

class QuantMatmulKernel {
public:
    __aicore__ inline QuantMatmulKernel() {}
    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tiling, TPipe &pipe);
    __aicore__ inline void Process();

    MatmulKernel<int8_t, int8_t, int32_t> mm_;
    GlobalTensor<int8_t> aGM_;
    GlobalTensor<int8_t> bGM_;
    GlobalTensor<int32_t> cGM_;
    QuantMatmulTiling tiling_;
    BlockScheduler sched_;
};

__aicore__ inline void QuantMatmulKernel::Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tilingGM, TPipe &pipe)
{
    CopyTiling(&tiling_, tilingGM);
    aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(a), tiling_.M * tiling_.K);
    bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(b), tiling_.K * tiling_.N);
    cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(c), tiling_.M * tiling_.N);

    int coreIdx = GetBlockIdx();
    sched_.Init(tiling_.M, tiling_.N, tiling_.baseM, tiling_.baseN, GetBlockNum(), coreIdx);
    mm_.Init(tiling_.K, tiling_.K, tiling_.N, pipe);
}

__aicore__ inline void QuantMatmulKernel::Process()
{
    int mIdx, nIdx;
    while (sched_.HasNext()) {
        sched_.Next(mIdx, nIdx);
        auto aBlock = aGM_[mIdx * tiling_.baseM * tiling_.K];
        auto bBlock = bGM_[nIdx * tiling_.baseN];
        auto cBlock = cGM_[mIdx * tiling_.baseM * tiling_.N + nIdx * tiling_.baseN];
        mm_.ComputeBlock(aBlock, bBlock, cBlock);
    }
}
