#include "torch_kernel_helper.h"
#include "aclrtlaunch_quant_matmul.h"
#include "quant_matmul_tiling.h"

static int32_t AlignUp(int32_t v, int32_t align) {
    return ((v + align - 1) / align) * align;
}

namespace ascend_kernel {

at::Tensor quant_matmul(
    const at::Tensor &a, const at::Tensor &b,
    const at::Tensor &scale, const at::Tensor &per_token_scale)
{
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "a,b must be 2D");
    TORCH_CHECK(a.scalar_type() == at::kChar, "a must be int8");
    TORCH_CHECK(b.scalar_type() == at::kChar, "b must be int8");

    at::Tensor a_contig = a.contiguous();
    at::Tensor b_contig = b.contiguous();

    int32_t m = static_cast<int32_t>(a.sizes()[0]);
    int32_t n = static_cast<int32_t>(b.sizes()[1]);
    int32_t k = static_cast<int32_t>(a.sizes()[1]);

    int32_t k_l1 = 3 * DEFAULT_BASE_K;
    int32_t m_pad = AlignUp(m, DEFAULT_BASE_M);
    int32_t n_pad = AlignUp(n, DEFAULT_BASE_N);
    int32_t k_pad = AlignUp(k, k_l1);

    at::Tensor a_pad = at::zeros({static_cast<int64_t>(m_pad), static_cast<int64_t>(k_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kChar));
    a_pad.slice(1, 0, k).slice(0, 0, m).copy_(a_contig);

    at::Tensor b_pad = at::zeros({static_cast<int64_t>(k_pad), static_cast<int64_t>(n_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kChar));
    b_pad.slice(0, 0, k).slice(1, 0, n).copy_(b_contig);

    // Output int32 [m_pad, n_pad]
    at::Tensor c_i32 = at::empty({static_cast<int64_t>(m_pad), static_cast<int64_t>(n_pad)},
                                  at::device(at::kPrivateUse1).dtype(at::kInt));

    // Tiling
    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(QuantMatmulTiling))},
                             at::device(at::kCPU).dtype(at::kByte));
    auto *tp = reinterpret_cast<QuantMatmulTiling *>(t.data_ptr());
    tp->M = m_pad;
    tp->N = n_pad;
    tp->K = k_pad;
    tp->baseM = DEFAULT_BASE_M;
    tp->baseN = DEFAULT_BASE_N;
    tp->baseK = DEFAULT_BASE_K;
    auto t_npu = t.to(at::kPrivateUse1);

    int32_t totalTiles = (m_pad / DEFAULT_BASE_M) * (n_pad / DEFAULT_BASE_N);
    uint32_t blockDim = static_cast<uint32_t>(totalTiles);
    EXEC_KERNEL_CMD(quant_matmul, blockDim, a_pad, b_pad, c_i32, t_npu);

    // Trim and convert to float32 with dequant on CPU
    at::Tensor c_valid = c_i32.slice(0, 0, m).slice(1, 0, n).contiguous();
    c_valid = c_valid.to(at::kFloat);

    at::Tensor s_cpu = scale.to(at::kFloat).contiguous().cpu();
    at::Tensor pt_cpu = per_token_scale.to(at::kFloat).contiguous().cpu();

    at::Tensor result = at::empty({static_cast<int64_t>(m), static_cast<int64_t>(n)},
                                   at::device(at::kCPU).dtype(at::kFloat));
    auto *c_ptr = c_valid.cpu().data_ptr<float>();
    auto *s_ptr = s_cpu.data_ptr<float>();
    auto *pt_ptr = pt_cpu.data_ptr<float>();
    auto *r_ptr = result.data_ptr<float>();

    for (int32_t i = 0; i < m; i++) {
        float pt_val = pt_ptr[i];
        for (int32_t j = 0; j < n; j++) {
            r_ptr[i * n + j] = c_ptr[i * n + j] * s_ptr[j] * pt_val;
        }
    }

    return result.to(a.device());
}

} // namespace ascend_kernel
